package creational.factory.projects.paymentgatewaysystem;

import creational.factory.projects.paymentgatewaysystem.enums.PaymentMethod;
import creational.factory.projects.paymentgatewaysystem.enums.PaymentRepository;
import creational.factory.projects.paymentgatewaysystem.model.Payment;
import creational.factory.projects.paymentgatewaysystem.service.PaymentService;

public class Main {

    public static void main(String[] args) {

        PaymentService paymentService = new PaymentService(PaymentRepository.HashMap);

        Payment payment = paymentService.createPayment(
                        2500,
                        PaymentMethod.CASH
                );

        paymentService.processPayment(payment.getPaymentId());

        paymentService.refundPayment(payment.getPaymentId());
    }
}

package creational.factory.projects.paymentgatewaysystem.enums;

public enum PaymentMethod {
    UPI,
    CREDIT_CARD,
    DEBIT_CARD,
    NET_BANKING,
    WALLET,
    CASH
}

package creational.factory.projects.paymentgatewaysystem.enums;

public enum PaymentRepository {
    HashMap
}

package creational.factory.projects.paymentgatewaysystem.enums;

public enum PaymentStatus {
    CREATED,
    PENDING,
    COMPLETED,
    FAILED,
    REFUNDED
}

package creational.factory.projects.paymentgatewaysystem.exception;

public class PaymentFailedException extends RuntimeException {
    public PaymentFailedException(String message) {
        super(message);
    }
}

package creational.factory.projects.paymentgatewaysystem.factory;

import creational.factory.projects.paymentgatewaysystem.enums.PaymentRepository;
import creational.factory.projects.paymentgatewaysystem.repository.IPaymentRepository;
import creational.factory.projects.paymentgatewaysystem.repository.MapPaymentRepository;

public class FPaymentRepository {
    public static IPaymentRepository getPaymentRepository(PaymentRepository method) {
        switch(method) {
            case HashMap -> {
                return new MapPaymentRepository();
            }
            default -> throw new IllegalArgumentException("Invalid payment method");
        }
    }
}

package creational.factory.projects.paymentgatewaysystem.factory;

import creational.factory.projects.paymentgatewaysystem.enums.PaymentMethod;
import creational.factory.projects.paymentgatewaysystem.strategy.*;

public class FPaymentStrategy {
    public static IPaymentStrategy getPaymentStrategy(PaymentMethod method) {
        switch(method) {
            case DEBIT_CARD -> {
                return new DebitCardPaymentStrategy();
            }
            case CREDIT_CARD -> {
                return new CreditCardPaymentStrategy();
            }
            case NET_BANKING -> {
                return new NetBankingPaymentStrategy();
            }
            case CASH -> {
                return new CashPaymentStrategy();
            }
            case UPI -> {
                return new UPIPaymentStrategy();
            }
            case WALLET -> {
                return new WalletPaymentStrategy();
            }
            default -> throw new IllegalArgumentException("Invalid payment method");
        }
    }
}

package creational.factory.projects.paymentgatewaysystem.model;
import java.util.UUID;

import creational.factory.projects.paymentgatewaysystem.enums.PaymentMethod;
import creational.factory.projects.paymentgatewaysystem.enums.PaymentStatus;

public class Payment {
    private final UUID paymentId;
    private final double amount;
    private PaymentStatus status;
    private final PaymentMethod method;
    private final long timestamp;

    public Payment(double amount) {
        this.paymentId = UUID.randomUUID();
        this.amount = amount;
        this.status = PaymentStatus.PENDING;
        this.method = PaymentMethod.CASH;
        this.timestamp = System.currentTimeMillis();
    }

    public Payment(double amount, PaymentMethod method) {
        this.paymentId = UUID.randomUUID();
        this.amount = amount;
        this.status = PaymentStatus.PENDING;
        this.method = method;
        this.timestamp = System.currentTimeMillis();
    }
    public String getPaymentId() {
        return paymentId.toString();
    }
    public double getAmount() {
        return amount;
    }
    public PaymentStatus getStatus() {
        return status;
    }
    public PaymentMethod getMethod() {
        return method;
    }
    public long getTimestamp() {
        return timestamp;
    } 
    public void setStatus(PaymentStatus status) {
        this.status = status;
    } 
}

package creational.factory.projects.paymentgatewaysystem.repository;

import creational.factory.projects.paymentgatewaysystem.model.Payment;

public interface IPaymentRepository {
    void save(Payment payment);
    Payment get(String paymentId);
}

package creational.factory.projects.paymentgatewaysystem.repository;

